/** Actual locked offhand defense and native slow travel; source has no blocking or movement authority. */
public final class ShieldWalkRigClientTest implements FabricClientGameTest {
    private static void check(boolean ok,String text){if(!ok)throw new AssertionError(text);}
    private static class Goal extends ZombieAttackGoal{Goal(Husk h){super(h,1,true);}void attempt(LivingEntity p){checkAndPerformAttack(p);}}
    private static AvatarRenderState state(Minecraft c){return (AvatarRenderState)c.getEntityRenderDispatcher().getRenderer(c.player).createRenderState(c.player,1);}
    private static CombatRigLayer.Frame frame(Minecraft c){return state(c).getData(CombatRigLayer.FRAME);}
    private static KeyMapping key(Options o,String d){return switch(d){case "forward"->o.keyUp;case "backward"->o.keyDown;case "left"->o.keyLeft;default->o.keyRight;};}
    private static void release(ClientGameTestContext c){c.getInput().releaseKey(v->v.keyUp);c.getInput().releaseKey(v->v.keyDown);c.getInput().releaseKey(v->v.keyLeft);c.getInput().releaseKey(v->v.keyRight);c.getInput().releaseKey(WildcraftBindings.DEFEND);c.getInput().releaseKey(WildcraftBindings.DODGE);}
    private static PlayerSkin skin(PlayerModelType t){for(int i=0;i<100;i++){var s=DefaultPlayerSkin.get(new UUID(0,i));if(s.model()==t)return s;}throw new AssertionError("Skin fixture");}
    private static void prepare(ClientGameTestContext c,TestSingleplayerContext w,int id,PlayerModelType type,HumanoidArm arm){
        release(c);c.waitTicks(16);w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();p.stopUsingItem();MeleeActions.receive(p,new MeleeIntent(MeleeIntent.CANCEL,(byte)0));ParryActions.reset(p);ReactionTime.cancel(p);p.teleportTo(p.level(),.5,120,.5,Set.of(),0,0,true);p.setDeltaMovement(Vec3.ZERO);p.setHealth(20);p.setInvulnerableTime(0);p.setItemSlot(EquipmentSlot.CHEST,ItemStack.EMPTY);p.setMainArm(arm);PlayerStamina.fill(p);p.getInventory().clearContent();p.getInventory().setSelectedSlot(0);var sword=new ItemStack(Items.IRON_SWORD);var shield=new ItemStack(Items.SHIELD);shield.set(net.minecraft.core.component.DataComponents.BASE_COLOR,DyeColor.BLUE);shield.set(net.minecraft.core.component.DataComponents.ENCHANTMENT_GLINT_OVERRIDE,true);check(FusionItems.attach(sword,new ItemStack(Items.COBBLESTONE),s.registryAccess())&&FusionItems.attach(shield,new ItemStack(Items.COBBLESTONE),s.registryAccess()),"Real native Fuse fixtures");p.setItemInHand(InteractionHand.MAIN_HAND,sword);p.setItemInHand(InteractionHand.OFF_HAND,shield);p.inventoryMenu.broadcastChanges();var m=(Husk)s.overworld().getEntity(id);ThreatActions.cancel(m);m.setTarget(p);m.setPos(.5,120,9.5);m.setHealth(20);CounterAttackAudit.begin(p);});
        c.waitFor(v->v.player.position().distanceTo(new Vec3(.5,120,.5))<.1&&v.player.onGround()&&v.player.getMainArm()==arm&&v.player.getOffhandItem().is(Items.SHIELD)&&v.player.getItemBySlot(EquipmentSlot.CHEST).isEmpty());c.runOnClient(v->{v.player.setYRot(0);v.player.setXRot(0);RigAudit.fixture=skin(type);RigAudit.begin();GuardRigAudit.begin();});c.waitTicks(4);if(!c.computeOnClient(v->Combat.locked(v.player))){c.getInput().holdKeyFor(WildcraftBindings.LOCK_TARGET,1);c.waitFor(v->Combat.locked(v.player));}
    }
    private static void soles(Minecraft c){
        var s=state(c);var f=s.getData(CombatRigLayer.FRAME);check(f!=null&&f.clip().contains("_cycle_guard_"),"Actual guard cycle");var d=f.data();var transforms=new Matrix4f[d.skinBones()];var normals=new Matrix3f[d.skinBones()];for(int i=0;i<transforms.length;i++){transforms[i]=new Matrix4f(f.global()[i]).mul(new Matrix4f().set(d.inverseBind()[i]));normals[i]=transforms[i].normal(new Matrix3f());}
        var feet=LockedWalkRig.feet(d.clips().get(f.clip()),f.time());int supports=0;for(int i=0;i<2;i++)if(feet[i][3]==1){check(Math.abs(LockedWalkRig.worldFoot(c.player.getPosition(1),s.bodyRot,feet[i]).y-120)<.012,"Actual flat supporting plane");String part=i==0?"left_leg":"right_leg";float lowest=Float.POSITIVE_INFINITY;for(var mesh:d.meshes())if(!mesh.outer()&&mesh.part().equals(part)){var vertices=CombatRig.deform(mesh,transforms,normals);for(int j=0;j<vertices.length;j+=8)lowest=Math.min(lowest,vertices[j+1]);}check(Math.abs(lowest)<.025,"Actual moving-guard skinned sole matches ground "+part+" "+lowest);supports++;}check(supports>0,"At least one authored support");
    }
    @Override public void runTest(ClientGameTestContext c){var id=new AtomicInteger();var opts=CombatOptions.get();boolean hold=opts.hold,jump=opts.jumpDodge;int follow=opts.follow;
        try(TestSingleplayerContext w=c.worldBuilder().create()){
            w.getConnection().waitForChunksRender();w.getServer().runCommand("gamemode survival @p");w.getServer().runCommand("time set day");w.getServer().runOnServer(s->{for(int x=-12;x<=12;x++)for(int z=-12;z<=12;z++)s.overworld().setBlockAndUpdate(new BlockPos(x,119,z),Blocks.STONE.defaultBlockState());var p=s.getPlayerList().getPlayers().getFirst();p.teleportTo(.5,120,.5);var m=EntityTypes.HUSK.create(s.overworld(),EntitySpawnReason.COMMAND);m.setPos(.5,120,9.5);m.setNoAi(true);m.setNoGravity(true);s.overworld().addFreshEntity(m);id.set(m.getId());});c.waitFor(v->v.player.getY()>119&&v.level.getEntity(id.get())!=null);c.getInput().resizeWindow(1280,960);c.runOnClient(v->{opts.hold=false;opts.follow=0;opts.jumpDodge=false;v.options.guiScale().set(2);v.options.setCameraType(CameraType.THIRD_PERSON_FRONT);});c.waitFor(v->ActionInput.tickFrame().gameplay());
            for(var type:PlayerModelType.values())for(var arm:HumanoidArm.values())for(String dir:new String[]{"forward","backward","left","right"}){
                prepare(c,w,id.get(),type,arm);c.getInput().holdKey(WildcraftBindings.DEFEND);c.waitFor(v->v.player.isUsingItem()&&Combat.view(v.player).defending());c.getInput().holdKey(v->key(v,dir));String expected="walk_"+dir+"_cycle_guard_"+(arm==HumanoidArm.RIGHT?"R":"L");c.waitFor(v->frame(v)!=null&&frame(v).clip().equals(expected));c.waitTicks(3);c.runOnClient(ShieldWalkRigClientTest::soles);check(c.computeOnClient(v->RigAudit.bodies>0&&RigAudit.hands>0&&RigAudit.shields>0&&RigAudit.texture.equals(RigAudit.fixture.body().texturePath().toString())),"Actual native skin/blue glint Fuse shield and sword reach GPU");c.takeScreenshot("shield-walk-real-"+dir+"-"+type+"-"+arm);c.runOnClient(v->v.options.setCameraType(CameraType.THIRD_PERSON_BACK));c.takeScreenshot("shield-walk-real-body-back-"+dir+"-"+type+"-"+arm);c.runOnClient(v->v.options.setCameraType(CameraType.THIRD_PERSON_FRONT));
                Vec3 from=c.computeOnClient(v->v.player.position());float phase=c.computeOnClient(v->frame(v).time()),stride=c.computeOnClient(v->frame(v).data().clips().get(expected).distance());c.waitTicks(3);Vec3 to=c.computeOnClient(v->v.player.position());float advanced=c.computeOnClient(v->frame(v).time());check(to.distanceTo(from)>.008&&to.distanceTo(from)<.20&&Math.abs((advanced-phase+1)%1-(to.distanceTo(from)/stride)%1)<.1,"Actual shield-slowed movement drives the approved distance phase");
                w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();check(p.isUsingItem()&&p.getUsedItemHand()==InteractionHand.OFF_HAND&&p.getHealth()==20&&CounterAttackAudit.calls==0&&p.getMainHandItem().getDamageValue()==0&&p.getOffhandItem().getDamageValue()==0&&p.getMainHandItem().get(FusionContent.DATA).remaining()==32&&p.getOffhandItem().get(FusionContent.DATA).remaining()==32&&PlayerStamina.get(p).stamina()==100,"Source movement has no invented block/attack/wear/Fuse/stamina/health effect");});c.getInput().releaseKey(v->key(v,dir));c.waitTicks(10);check(c.computeOnClient(v->frame(v)==null||!frame(v).clip().startsWith("walk_")),"Stopped guard relinquishes gait to current guard/native body");c.takeScreenshot("shield-walk-stopped-"+dir+"-"+type+"-"+arm);c.getInput().releaseKey(WildcraftBindings.DEFEND);
            }
            // Held movement into an actual wall must freeze the cycle while preserving actual defense.
            prepare(c,w,id.get(),PlayerModelType.WIDE,HumanoidArm.RIGHT);w.getServer().runOnServer(s->{for(int y=120;y<=123;y++)for(int z=-4;z<=4;z++)s.overworld().setBlockAndUpdate(new BlockPos(1,y,z),Blocks.STONE.defaultBlockState());});c.getInput().holdKey(WildcraftBindings.DEFEND);c.waitFor(v->v.player.isUsingItem());c.getInput().holdKey(v->v.keyLeft);c.waitFor(v->v.player.horizontalCollision);c.waitTicks(10);Vec3 wall=c.computeOnClient(v->v.player.position());c.waitTicks(5);check(c.computeOnClient(v->v.player.isUsingItem()&&v.player.position().distanceTo(wall)<.005&&(frame(v)==null||!frame(v).clip().contains("_cycle_"))),"Actual wall stops gait without releasing native defense");c.takeScreenshot("shield-walk-real-wall-stop");release(c);w.getServer().runOnServer(s->{for(int y=120;y<=123;y++)for(int z=-4;z<=4;z++)s.overworld().setBlockAndUpdate(new BlockPos(1,y,z),Blocks.AIR.defaultBlockState());});
            prepare(c,w,id.get(),PlayerModelType.WIDE,HumanoidArm.RIGHT);c.getInput().holdKey(WildcraftBindings.DEFEND);c.getInput().holdKey(v->v.keyUp);c.waitFor(v->frame(v)!=null&&frame(v).clip().contains("_cycle_guard_"));c.getInput().releaseKey(WildcraftBindings.DEFEND);c.waitFor(v->!v.player.isUsingItem()&&frame(v)!=null&&frame(v).clip().contains("_cycle_carry_"));c.takeScreenshot("shield-walk-real-release-to-carry");release(c);
            prepare(c,w,id.get(),PlayerModelType.WIDE,HumanoidArm.RIGHT);c.getInput().holdKey(WildcraftBindings.DEFEND);c.getInput().holdKey(v->v.keyUp);c.waitFor(v->frame(v)!=null&&frame(v).clip().contains("_cycle_guard_"));c.getInput().releaseKey(v->v.keyUp);c.getInput().holdKey(v->v.keyDown);c.getInput().holdKeyFor(WildcraftBindings.DODGE,1);c.waitFor(v->MeleeActions.hopping(v.player));check(c.computeOnClient(v->!v.player.isUsingItem()&&frame(v)!=null&&frame(v).clip().startsWith("dodge_")),"Actual HOP releases shield and owns body, no moving-source block privilege");c.takeScreenshot("shield-walk-real-hop-release");c.waitFor(v->!MeleeActions.hopping(v.player)&&v.player.isUsingItem());release(c);
            prepare(c,w,id.get(),PlayerModelType.WIDE,HumanoidArm.RIGHT);c.getInput().holdKey(WildcraftBindings.DEFEND);c.getInput().holdKey(v->v.keyUp);c.waitFor(v->frame(v)!=null&&frame(v).clip().contains("_cycle_guard_"));c.setScreen(()->new InventoryScreen(Minecraft.getInstance().player));check(c.computeOnClient(v->frame(v)==null),"GUI owns guard gait immediately");c.takeScreenshot("shield-walk-gui-owner");c.setScreen(()->null);release(c);
            prepare(c,w,id.get(),PlayerModelType.WIDE,HumanoidArm.RIGHT);w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();p.setItemSlot(EquipmentSlot.CHEST,new ItemStack(Items.IRON_CHESTPLATE));p.inventoryMenu.broadcastChanges();});c.waitFor(v->v.player.getItemBySlot(EquipmentSlot.CHEST).is(Items.IRON_CHESTPLATE));c.getInput().holdKey(WildcraftBindings.DEFEND);c.getInput().holdKey(v->v.keyUp);c.waitFor(v->v.player.isUsingItem());c.waitTicks(8);check(c.computeOnClient(v->frame(v)==null),"Actual armor retains original moving defense");c.takeScreenshot("shield-walk-native-armor");release(c);
            prepare(c,w,id.get(),PlayerModelType.WIDE,HumanoidArm.RIGHT);c.getInput().holdKey(WildcraftBindings.DEFEND);c.getInput().holdKey(v->v.keyUp);c.waitFor(v->frame(v)!=null&&frame(v).clip().contains("_cycle_guard_"));c.getInput().holdKey(v->v.keyLeft);c.waitTicks(4);check(c.computeOnClient(v->frame(v)==null||!frame(v).clip().startsWith("walk_")),"Unqualified diagonal retains previous guard/native presentation");c.takeScreenshot("shield-walk-native-diagonal");release(c);
            prepare(c,w,id.get(),PlayerModelType.WIDE,HumanoidArm.RIGHT);c.getInput().holdKey(WildcraftBindings.DEFEND);c.getInput().holdKey(v->v.keyUp);c.waitFor(v->frame(v)!=null&&frame(v).clip().contains("_cycle_guard_"));c.getInput().holdKeyFor(WildcraftBindings.LOCK_TARGET,1);c.waitFor(v->!Combat.locked(v.player));check(c.computeOnClient(v->frame(v)==null||!frame(v).clip().startsWith("walk_")),"Real unlock relinquishes distance gait");c.takeScreenshot("shield-walk-real-unlock");release(c);
            prepare(c,w,id.get(),PlayerModelType.WIDE,HumanoidArm.RIGHT);c.getInput().holdKey(WildcraftBindings.DEFEND);c.getInput().holdKey(v->v.keyUp);c.waitFor(v->frame(v)!=null&&frame(v).clip().contains("_cycle_guard_"));c.getInput().releaseKey(WildcraftBindings.DEFEND);c.waitFor(v->!v.player.isUsingItem());c.runOnClient(v->{v.options.keyAttack.setDown(true);ActionInput.frame(v);v.options.keyAttack.setDown(false);ActionInput.frame(v);});c.waitFor(v->MeleeActions.view(v.player).phase()==MeleeView.SWING);check(c.computeOnClient(v->frame(v)==null||!frame(v).clip().startsWith("walk_")),"Actual legal attack after shield release owns body");c.takeScreenshot("shield-walk-real-attack-after-release");release(c);
            prepare(c,w,id.get(),PlayerModelType.WIDE,HumanoidArm.RIGHT);c.getInput().holdKey(WildcraftBindings.DEFEND);c.getInput().holdKey(v->v.keyUp);c.waitFor(v->frame(v)!=null&&frame(v).clip().contains("_cycle_guard_"));w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();p.hurtServer(s.overworld(),p.damageSources().generic(),1);check(p.getHealth()<20,"Moving art adds no damage immunity");});c.waitFor(v->v.player.getHealth()<20&&MeleeActions.view(v.player).hurt()>0);check(c.computeOnClient(v->frame(v)==null||!frame(v).clip().startsWith("walk_")),"Actual hurt owns body immediately");c.takeScreenshot("shield-walk-real-hurt");release(c);
            // Real native goal starts while unguarded carry walks; fresh DEFEND before impact earns the original C4 event.
            for(var type:PlayerModelType.values())for(var arm:HumanoidArm.values()){
                prepare(c,w,id.get(),type,arm);w.getServer().runOnServer(s->s.overworld().getEntity(id.get()).setPos(.5,120,2));c.getInput().holdKey(v->v.keyUp);c.waitFor(v->frame(v)!=null&&frame(v).clip().contains("_cycle_carry_"));w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();new Goal((Husk)s.overworld().getEntity(id.get())).attempt(p);});c.getInput().releaseKey(v->v.keyUp);c.waitFor(v->ThreatActions.view((LivingEntity)v.level.getEntity(id.get())).age()>=6);c.getInput().holdKey(WildcraftBindings.DEFEND);c.getInput().holdKey(v->v.keyDown);c.waitFor(v->ThreatActions.view((LivingEntity)v.level.getEntity(id.get())).age()>=10);w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();new Goal((Husk)s.overworld().getEntity(id.get())).attempt(p);System.out.println("C6N MOVING GOAL actual hit player="+p.position()+" health="+p.getHealth()+" guard="+ParryActions.view(p));});c.waitFor(v->ParryActions.view(v.player).remaining()>0&&frame(v)!=null&&frame(v).clip().contains("_guard_")&&GuardRigAudit.activeDeviation>.005);w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();check(p.isUsingItem()&&p.getHealth()==20&&p.getOffhandItem().getDamageValue()>0&&p.getOffhandItem().get(FusionContent.DATA).remaining()==31&&CounterAttackAudit.calls==0&&PlayerStamina.get(p).stamina()==100&&ThreatActions.staggered((LivingEntity)s.overworld().getEntity(id.get())),"Actual moving fresh shield block owns original wear/Fuse/stagger, no source costs or attacks");s.overworld().getEntity(id.get()).teleportTo(.5,120,8);});c.takeScreenshot("shield-walk-real-moving-parry-"+type+"-"+arm);c.waitTicks(10);check(c.computeOnClient(v->state(v).getData(GuardRig.PULSE)==null&&v.player.isUsingItem()),"Original eight-world-tick arm pulse ends while real moving defense persists");release(c);
            }
            System.out.println("C6N actual locked DEFEND/four directions/wide-slim/left-right, native slow distance/real skinned flat soles/GPU, no free effects, stops/wall/carry/HOP/GUI/armor, actual moving goal/fresh block-wear-Fuse-stagger and active-arm-only pulse PASS");
        }finally{release(c);c.runOnClient(v->{GuardRigAudit.enabled=false;RigAudit.enabled=false;RigAudit.fixture=null;opts.hold=hold;opts.follow=follow;opts.jumpDodge=jump;v.options.setCameraType(CameraType.FIRST_PERSON);});}
    }
}
